export function createIn(directory, schema) {
  return new InMemoryIndex(directory, schema);
}

class InMemoryIndex {
  constructor(directory, schema) {
    this.directory = directory;
    this.schema = schema;
    this.documents = [];
  }

  writer() {
    return new IndexWriter(this);
  }

  searcher() {
    return new Searcher(this.documents);
  }
}

class IndexWriter {
  constructor(index) {
    this.index = index;
    this.pending = [];
  }

  addDocument(document) {
    this.pending.push({ ...document });
  }

  commit() {
    this.index.documents.push(...this.pending);
    this.pending = [];
  }
}

class Searcher {
  constructor(documents) {
    this.documents = documents;
  }

  search(query, limit = 10) {
    const results = [];
    for (const document of this.documents) {
      if (query.matches(document)) {
        results.push(document);
      }
      if (results.length >= limit) {
        break;
      }
    }
    return results;
  }
}

