function buildTermNode(fieldName, fieldDef, rawText) {
  if (!fieldDef) {
    return NULL_QUERY;
  }

  if (fieldDef.kind === 'numeric') {
    const normalized = normalizeRawTerm(rawText);
    const value = parseIntegerLiteral(normalized);
