  const upper = upperRaw === '*' || upperRaw === '' ? null : parseIntegerLiteral(upperRaw);

  if ((lowerRaw !== '*' && lowerRaw !== '' && lower === null) || (upperRaw !== '*' && upperRaw !== '' && upper === null)) {
    return NULL_QUERY;
  }

  return {
    type: 'numeric_range',
    field: fieldName,
    lower,
    upper,
    includeLower: token.includeLower,
    includeUpper: token.includeUpper,
  };
}

