class ParsedQuery {
  constructor(ast) {
    this.ast = ast;
  }

  matches(document) {
    return evaluateNode(this.ast, document);
  }
}

export class QueryParser {
  constructor(defaultField, schema) {
    this.defaultField = defaultField;
    this.schema = schema;
  }

  parse(text) {
    const ast = new InternalParser(this.defaultField, this.schema, String(text ?? '')).parse();
    return new ParsedQuery(ast);
  }
}
